#!/usr/bin/env node
// Applies the Simplizzia standard to a freshly created Next.js app. Rules are copied from
// templates by this script, never regenerated by the agent; only the brief is project-specific.
//
//   node scaffold.mjs --dir <app-dir> --tier <1|2|3> --brief <brief.md> [--install]
//   node scaffold.mjs --info      facts for the new-project skill (lead, org, versions, folder)
import { existsSync, mkdirSync, readdirSync, readFileSync, writeFileSync } from 'node:fs';
import { basename, dirname, join, relative, resolve } from 'node:path';
import { parseArgs } from 'node:util';

import { isEmptyDir, loadConfig, PLUGIN_ROOT, run, toPosix } from './lib.mjs';

// Majors verified together: typescript-eslint 8 needs TypeScript < 6.1 and eslint-plugin-react
// (inside eslint-config-next) needs ESLint 9. Do not bump them without re-running the checks.
const DEPENDENCIES = [
  'zod@^4',
  'next-safe-action@^8',
  '@t3-oss/env-nextjs@^0.13',
  '@supabase/ssr@^0.12',
  '@supabase/supabase-js@^2',
  'server-only',
  'react-hook-form@^7',
  '@hookform/resolvers@^5',
];
const DEV_DEPENDENCIES = ['typescript-eslint@^8'];
const TEMPLATE_DIR = join(PLUGIN_ROOT, 'templates', 'project');
const PLACEHOLDER_FILES = /(?:\.md|\.json|\.example|\.yml)$/;

const { values: args } = parseArgs({
  options: {
    dir: { type: 'string' },
    tier: { type: 'string' },
    brief: { type: 'string' },
    install: { type: 'boolean', default: false },
    info: { type: 'boolean', default: false },
  },
});

function printInfo() {
  const config = loadConfig();
  const cwd = process.cwd();
  const name = basename(cwd);
  const validName = /^[a-z0-9][a-z0-9._-]{0,213}$/.test(name);
  const gh = run('gh auth status', cwd, 15_000);
  process.stdout.write(
    [
      `Lead: ${config.leadName}`,
      `GitHub organization: ${config.githubOrg}`,
      `Standard version: ${config.standardVersion}`,
      `Next.js: ${config.nextVersion}`,
      `Create command: npx --yes create-next-app@${config.nextVersion} <folder> --ts --tailwind --eslint --app --src-dir --import-alias "@/*" --use-npm --yes --disable-git`,
      `Current folder: ${cwd}`,
      `Current folder empty: ${isEmptyDir(cwd) ? 'yes' : 'no'}`,
      `Current folder name valid for a project: ${validName ? 'yes' : 'no (use a kebab-case subfolder)'}`,
      `GitHub CLI logged in: ${gh.code === 0 ? 'yes' : 'no'}`,
    ].join('\n') + '\n',
  );
}

function fail(message) {
  process.stderr.write(`sz scaffold: ${message}\n`);
  process.exit(1);
}

function readJson(file) {
  return JSON.parse(readFileSync(file, 'utf8'));
}

function writeJson(file, data) {
  writeFileSync(file, `${JSON.stringify(data, null, 2)}\n`);
}

function templateFiles(dir = TEMPLATE_DIR, found = []) {
  for (const entry of readdirSync(dir, { withFileTypes: true })) {
    const path = join(dir, entry.name);
    if (entry.isDirectory()) templateFiles(path, found);
    else found.push(toPosix(relative(TEMPLATE_DIR, path)));
  }
  return found;
}

function fill(text, vars) {
  return text.replace(/\{\{(\w+)\}\}/g, (match, key) => (key in vars ? String(vars[key]) : match));
}

function validate(dir) {
  if (args.dir === undefined || args.tier === undefined || args.brief === undefined) {
    fail('uso: node scaffold.mjs --dir <app> --tier <1|2|3> --brief <brief.md> [--install]');
  }
  const pkgFile = join(dir, 'package.json');
  if (!existsSync(pkgFile)) fail(`${dir} não tem package.json. Rode create-next-app antes.`);
  const pkg = readJson(pkgFile);
  if (typeof pkg.dependencies?.next !== 'string') fail('o projeto não depende de next.');
  if (!existsSync(join(dir, 'src', 'app'))) fail('esperado src/app (create-next-app com --src-dir --app).');
  if (existsSync(join(dir, '.sz', 'project.json'))) fail('o projeto já tem .sz/project.json; o scaffold roda uma vez só.');
  if (!['1', '2', '3'].includes(args.tier)) fail('--tier precisa ser 1, 2 ou 3.');
  const brief = existsSync(args.brief) ? readFileSync(args.brief, 'utf8').trim() : '';
  if (brief === '') fail(`brief vazio ou inexistente: ${args.brief}`);
  return { pkg, brief };
}

function copyTemplates(dir, vars) {
  const written = [];
  for (const rel of templateFiles()) {
    const target = join(dir, rel);
    mkdirSync(dirname(target), { recursive: true });
    const content = readFileSync(join(TEMPLATE_DIR, rel), 'utf8');
    writeFileSync(target, PLACEHOLDER_FILES.test(rel) ? fill(content, vars) : content);
    written.push(rel);
  }
  return written;
}

function patchTsconfig(dir) {
  const file = join(dir, 'tsconfig.json');
  const tsconfig = readJson(file);
  tsconfig.compilerOptions = {
    ...tsconfig.compilerOptions,
    strict: true,
    noUncheckedIndexedAccess: true,
    noImplicitReturns: true,
    noFallthroughCasesInSwitch: true,
  };
  writeJson(file, tsconfig);
}

function patchPackage(dir) {
  const file = join(dir, 'package.json');
  const pkg = readJson(file);
  pkg.scripts = {
    ...pkg.scripts,
    // next typegen writes the global route types (LayoutProps, PageProps) and the validator
    // that checks route handler signatures; plain tsc fails on a fresh Next 16 app without it.
    typecheck: 'next typegen && tsc --noEmit',
    lint: 'eslint . --max-warnings 0',
    check: 'npm run typecheck && npm run lint',
    deploy:
      pkg.scripts?.deploy ??
      "node -e \"console.error('Deploy ainda não configurado para este projeto. Combine com o lead (Vercel ou VPS).'); process.exit(1)\"",
  };
  writeJson(file, pkg);
}

function patchGitignore(dir) {
  const file = join(dir, '.gitignore');
  const current = existsSync(file) ? readFileSync(file, 'utf8') : '';
  const additions = ['!.env.example', '.sz/reports/'].filter((line) => !current.split('\n').includes(line));
  if (additions.length > 0) writeFileSync(file, `${current.trimEnd()}\n\n# sz standard\n${additions.join('\n')}\n`);
}

function install(dir) {
  const steps = [
    `npm install --no-fund --no-audit ${DEPENDENCIES.join(' ')}`,
    `npm install --no-fund --no-audit --save-dev ${DEV_DEPENDENCIES.join(' ')}`,
  ];
  for (const command of steps) {
    process.stdout.write(`> ${command}\n`);
    const result = run(command, dir, 600_000);
    if (result.code !== 0) fail(`falhou: ${command}\n${result.stderr.slice(-2000)}`);
  }
}

function main() {
  if (args.info) {
    printInfo();
    return;
  }
  const dir = resolve(args.dir ?? '.');
  const config = loadConfig();
  const { pkg, brief } = validate(dir);
  const nextVersion = pkg.dependencies.next.replace(/^[\^~]/, '');
  const vars = {
    PROJECT_NAME: pkg.name,
    TIER: args.tier,
    STANDARD_VERSION: config.standardVersion,
    NEXT_VERSION: nextVersion,
    DATE: new Date().toISOString().slice(0, 10),
    BRIEF: brief,
    STANDARD_REPO: config.standardRepo,
    STANDARD_REF: config.standardRef,
  };
  const written = copyTemplates(dir, vars);
  writeFileSync(join(dir, '.sz', 'brief.md'), `${brief}\n`);
  patchTsconfig(dir);
  patchPackage(dir);
  patchGitignore(dir);
  if (args.install) install(dir);

  const lines = [
    `Padrão ${config.standardVersion} aplicado em ${dir} (nível ${args.tier}).`,
    `Arquivos do template: ${String(written.length)}. Configs ajustadas: tsconfig.json, package.json, .gitignore.`,
  ];
  if (nextVersion !== config.nextVersion) {
    lines.push(`Atenção: o projeto usa next ${nextVersion} e o padrão foi validado com ${config.nextVersion}. Avise o lead.`);
  }
  if (!args.install) lines.push(`Falta instalar: npm install ${DEPENDENCIES.join(' ')} && npm install -D ${DEV_DEPENDENCIES.join(' ')}`);
  lines.push('Próximo passo: npm run check.');
  process.stdout.write(`${lines.join('\n')}\n`);
}

main();
